import json

raw_json = '{"success":true,"title":"Instagram Post","thumbnail":"https://d.rapidcdn.app/thumb?token=eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9..oxyYFVUSFpgBm5FtCBCxm4DU0BWjuS27H0cTJlivuAY","url":"/api/proxy-download?url=https%3A%2F%2Fd.rapidcdn.app%2Fv2%3Ftoken=eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9..iIHu3DmFzbU0Ix_BLvkBEJqA8l1nL3W-scyPMwK4vZM%26dl%3D1%26dl%3D1&filename=instagram_image_item_1","mediaType":"image","media":[{"type":"image","url":"/api/proxy-download?url=https%3A%2F%2Fd.rapidcdn.app%2Fv2%3Ftoken=eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9..iIHu3DmFzbU0Ix_BLvkBEJqA8l1nL3W-scyPMwK4vZM%26dl%3D1%26dl%3D1&filename=instagram_image_item_1","thumbnail":"https://d.rapidcdn.app/thumb?token=eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9..oxyYFVUSFpgBm5FtCBCxm4DU0BWjuS27H0cTJlivuAY","id":"slide_1","mediaId":"slide_1","index":0,"shortcode":""}],"source":"btch"}'
data = json.loads(raw_json)

rootFilename = data.get("filename", "")
print(f"rootFilename: {rootFilename}")
arr = data.get("media", [])

for item in arr:
    qUrl = item.get("url", "")
    qLabel = item.get("type", "Download")

    print(f"Before: qLabel={qLabel}")
    if qLabel.lower() == "image" or qLabel.lower() == "video":
        if qLabel.lower() == "video" or ".mp4" in qUrl.lower():
            qLabel = "Video (MP4)"
        elif ".jpg" in qUrl.lower() or ".png" in qUrl.lower():
            qLabel = "Image (JPG)"
        else:
            qLabel = "Video (MP4)" if rootFilename.lower().endswith(".mp4") else "Image (JPG)"
    
    print(f"After: qLabel={qLabel}")
